INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('cost center', '成本中心', 'a department that incurs costs but does not directly generate revenue', '[{"en":"IT was historically treated as a cost center.","zh-TW":"IT部門過去一直被視為成本中心。"},{"en":"Transform the cost center into a value generator.","zh-TW":"將成本中心轉變為價值創造者。"}]', 'business idiom'),
('cost overrun', '成本超支；費用超預算', 'expenses that exceed the planned budget for a project', '[{"en":"Cost overruns on the project delayed the timeline.","zh-TW":"專案的成本超支推遲了時間表。"},{"en":"Rigorous cost tracking prevents unexpected cost overruns.","zh-TW":"嚴格的成本追蹤防止了意外的費用超支。"}]', 'business idiom'),
('critical path', '關鍵路徑；決定最短完工時間的工作序列', 'the sequence of dependent tasks that determines the minimum project duration', '[{"en":"Identify the critical path to avoid delaying the whole project.","zh-TW":"識別關鍵路徑以避免延誤整個專案。"},{"en":"Any delay on the critical path extends the project deadline.","zh-TW":"關鍵路徑上的任何延誤都會延長專案截止日期。"}]', 'business idiom'),
('customer acquisition cost', '客戶獲取成本', 'the total cost of acquiring a new customer through marketing and sales efforts', '[{"en":"Referral programs can reduce customer acquisition cost significantly.","zh-TW":"推薦計劃可以顯著降低客戶獲取成本。"},{"en":"Track customer acquisition cost by channel.","zh-TW":"按渠道追蹤客戶獲取成本。"}]', 'business idiom'),
('customer lifetime value', '客戶終身價值', 'the total revenue a business can expect from a single customer relationship', '[{"en":"Increasing customer lifetime value is more cost-effective than acquisition.","zh-TW":"提高客戶終身價值比獲取新客戶更具成本效益。"},{"en":"Calculate customer lifetime value to guide marketing spend.","zh-TW":"計算客戶終身價值以指導行銷支出。"}]', 'business idiom'),
('customer touchpoint', '客戶接觸點', 'any interaction between a customer and a company at any stage', '[{"en":"Map all customer touchpoints to improve the experience.","zh-TW":"繪製所有客戶接觸點以改善體驗。"},{"en":"Consistent messaging across every customer touchpoint builds trust.","zh-TW":"在每個客戶接觸點保持一致的信息建立信任。"}]', 'business idiom'),
('day-to-day operations', '日常運營；日常業務', 'the regular, routine activities that keep a business running', '[{"en":"She manages day-to-day operations while the CEO focuses on strategy.","zh-TW":"她管理日常運營而執行長專注於策略。"},{"en":"Automate day-to-day operations to free up management time.","zh-TW":"自動化日常運營以釋放管理層的時間。"}]', 'business idiom'),
('decision maker', '決策者', 'the person with the authority to make final decisions', '[{"en":"Identify the decision maker early in the sales process.","zh-TW":"在銷售流程的早期識別決策者。"},{"en":"Tailor your pitch to the decision maker''s priorities.","zh-TW":"根據決策者的優先事項量身訂制你的推介。"}]', 'business idiom'),
('emerging market', '新興市場', 'a country with a developing economy that offers growth opportunities', '[{"en":"Emerging markets are a major growth driver for our sector.","zh-TW":"新興市場是我們行業的主要增長驅動力。"},{"en":"Entry into emerging markets requires cultural adaptation.","zh-TW":"進入新興市場需要文化適應。"}]', 'business idiom'),
('enterprise solution', '企業解決方案', 'a product or service designed for large organizations', '[{"en":"We developed an enterprise solution for Fortune 500 clients.","zh-TW":"我們為財富500強客戶開發了企業解決方案。"},{"en":"Enterprise solutions require longer sales cycles.","zh-TW":"企業解決方案需要更長的銷售週期。"}]', 'business idiom'),
('find a middle ground', '找到折中方案；達成妥協', 'to reach a compromise between two opposing positions', '[{"en":"We found a middle ground on the contract length.","zh-TW":"我們在合約期限上找到了折中方案。"},{"en":"Good negotiators always look for a middle ground.","zh-TW":"優秀的談判者總是尋求達成妥協。"}]', 'expression'),
('first-mover advantage', '先發優勢', 'the competitive benefit of being the first to enter a new market', '[{"en":"Our first-mover advantage in mobile payments is significant.","zh-TW":"我們在移動支付領域的先發優勢是顯著的。"},{"en":"First-mover advantage quickly erodes without continuous innovation.","zh-TW":"沒有持續創新先發優勢很快就會消退。"}]', 'business idiom'),
('flat organization', '扁平化組織', 'a company with few or no levels of management between executives and staff', '[{"en":"A flat organization speeds up decision-making.","zh-TW":"扁平化組織加快了決策速度。"},{"en":"The startup operates as a flat organization to stay agile.","zh-TW":"新創公司以扁平化組織運作以保持靈活性。"}]', 'business idiom'),
('game plan', '行動計劃；策略計劃', 'a detailed strategy or plan of action', '[{"en":"We drafted a clear game plan before the merger.","zh-TW":"在合併之前我們制定了清晰的行動計劃。"},{"en":"Share the game plan with the entire team before launch.","zh-TW":"在發布前與整個團隊分享策略計劃。"}]', 'business idiom'),
('good faith effort', '誠信努力；真誠的嘗試', 'an honest and sincere attempt to do something', '[{"en":"We made a good faith effort to resolve the dispute.","zh-TW":"我們誠信地努力解決了這場爭議。"},{"en":"A good faith effort is expected before escalating issues.","zh-TW":"在升級問題之前應先做出真誠的嘗試。"}]', 'expression'),
('go-to-market strategy', '市場進入策略', 'the plan a company uses to launch a product into the market', '[{"en":"Our go-to-market strategy focuses on digital-first distribution.","zh-TW":"我們的市場進入策略專注於數位優先分銷。"},{"en":"A strong go-to-market strategy is essential for launch success.","zh-TW":"強大的市場進入策略對發布成功至關重要。"}]', 'business idiom'),
('hard stop', '硬性截止；絕對不超過的時間點', 'a non-negotiable end time or limit for a meeting or deadline', '[{"en":"I have a hard stop at 3 PM for another call.","zh-TW":"我在下午3點有硬性截止，要接另一個電話。"},{"en":"Set a hard stop on negotiations if no progress by Friday.","zh-TW":"如果週五前沒有進展就設定硬性截止談判。"}]', 'business idiom'),
('headcount freeze', '凍結人員編制；停止招聘', 'a temporary ban on hiring new employees', '[{"en":"A headcount freeze was announced during the budget review.","zh-TW":"預算審查期間宣布了凍結人員編制。"},{"en":"The headcount freeze affected all departments equally.","zh-TW":"凍結人員編制對所有部門都有同等影響。"}]', 'business idiom'),
('high-level overview', '高層次概覽；整體概述', 'a broad summary without detailed specifics', '[{"en":"Give the board a high-level overview of the project.","zh-TW":"向董事會提供專案的高層次概覽。"},{"en":"Start with a high-level overview before diving into details.","zh-TW":"在深入細節之前先提供整體概述。"}]', 'expression'),
('hold the line', '守住底線；堅守立場', 'to maintain a position or standard under pressure', '[{"en":"We held the line on pricing despite competitive pressure.","zh-TW":"儘管面臨競爭壓力我們守住了定價底線。"},{"en":"Hold the line on quality standards no matter the pressure.","zh-TW":"無論壓力多大都要堅守品質標準。"}]', 'expression'),
('horizontal expansion', '水平擴張；橫向擴展', 'growth by moving into new markets at the same level of the supply chain', '[{"en":"Horizontal expansion into adjacent markets boosted revenue.","zh-TW":"水平擴張進入相鄰市場提升了收入。"},{"en":"Horizontal expansion is often faster than vertical integration.","zh-TW":"水平擴張往往比垂直整合速度更快。"}]', 'business idiom'),
('incentivize behavior', '激勵行為；用激勵機制促進', 'to motivate certain actions by offering rewards or benefits', '[{"en":"We incentivize upselling with a tiered bonus structure.","zh-TW":"我們用分層獎金結構激勵交叉銷售行為。"},{"en":"Incentivize customers to refer others through discounts.","zh-TW":"通過折扣激勵客戶向他人推薦。"}]', 'phrasal verb'),
('infer from', '從…推斷；根據…得出結論', 'to draw a conclusion from evidence or reasoning', '[{"en":"What can we infer from this trend in the data?","zh-TW":"我們能從數據中的這個趨勢推斷什麼？"},{"en":"Infer customer intent from their browsing behavior.","zh-TW":"根據客戶的瀏覽行為推斷其意圖。"}]', 'phrasal verb'),
('integrate into', '整合進；融入', 'to combine something into a larger system or structure', '[{"en":"We integrated the new API into the existing platform.","zh-TW":"我們將新的API整合進了現有平台。"},{"en":"Integrate sustainability into your core business model.","zh-TW":"將可持續發展融入你的核心商業模式。"}]', 'phrasal verb'),
('iterate on', '對…進行迭代；持續改進', 'to repeatedly refine and improve something based on feedback', '[{"en":"We iterate on the product monthly based on user feedback.","zh-TW":"我們根據用戶反饋每月對產品進行迭代。"},{"en":"Iterate on the prototype until it meets user expectations.","zh-TW":"對原型持續改進直到達到用戶期望。"}]', 'phrasal verb'),
('key into', '深入了解；切入核心', 'to tap into or connect with something significant', '[{"en":"Their campaign keyed into the emotions of young consumers.","zh-TW":"他們的活動深入了解年輕消費者的情感。"},{"en":"Key into what your audience truly values.","zh-TW":"切入核心了解你的受眾真正重視什麼。"}]', 'phrasal verb'),
('knock out', '消除；淘汰；完成（任務）', 'to eliminate or complete quickly and efficiently', '[{"en":"Let''s knock out the easy items on the agenda first.","zh-TW":"讓我們先快速完成議程上容易的項目。"},{"en":"Knock out your competitors by outperforming on service.","zh-TW":"通過在服務上表現更好來淘汰競爭對手。"}]', 'phrasal verb'),
('lay down', '制定（規則）；確立', 'to establish rules, principles, or guidelines firmly', '[{"en":"The board laid down clear governance principles.","zh-TW":"董事會制定了清晰的治理原則。"},{"en":"Lay down ground rules before the negotiation begins.","zh-TW":"在談判開始前確立基本規則。"}]', 'phrasal verb'),
('lean into', '積極面對；主動投入；強化優勢', 'to embrace or fully engage with a situation, challenge, or strength', '[{"en":"Lean into your brand''s heritage to differentiate.","zh-TW":"積極利用品牌的傳承來差異化。"},{"en":"She leaned into the critical feedback and improved her pitch.","zh-TW":"她主動面對批評性反饋並改進了她的推介。"}]', 'phrasal verb'),
('leverage off', '借助…的優勢；從…中獲益', 'to use something as a foundation or advantage to advance', '[{"en":"We leveraged off the existing brand to launch the new line.","zh-TW":"我們借助現有品牌的優勢推出了新系列。"},{"en":"Leverage off your network to break into new markets.","zh-TW":"借助你的人脈進入新市場。"}]', 'phrasal verb'),
('make inroads into', '逐步進入；有所突破', 'to make progress in penetrating a market or solving a problem', '[{"en":"We''re making inroads into the enterprise market this year.","zh-TW":"今年我們正在逐步進入企業市場。"},{"en":"Make inroads into the competitor''s client base.","zh-TW":"在競爭對手的客戶群中有所突破。"}]', 'phrasal verb'),
('marshal resources', '整合調度資源；動員資源', 'to organize and deploy available resources efficiently', '[{"en":"We marshaled all available resources for the product launch.","zh-TW":"我們整合調度了所有可用資源以進行產品發布。"},{"en":"Marshal your best team for the most critical projects.","zh-TW":"為最關鍵的專案動員你最好的團隊。"}]', 'phrasal verb'),
('maximize potential', '最大化潛力；充分發揮', 'to use all available ability or opportunity to the fullest extent', '[{"en":"Our goal is to maximize the potential of each employee.","zh-TW":"我們的目標是最大化每位員工的潛力。"},{"en":"Maximize the potential of the technology before upgrading.","zh-TW":"在升級之前充分發揮技術的潛力。"}]', 'phrasal verb'),
('mitigate risks', '降低風險；緩解風險', 'to take action to reduce the likelihood or impact of risks', '[{"en":"Diversifying suppliers mitigates risks in the supply chain.","zh-TW":"多樣化供應商降低了供應鏈中的風險。"},{"en":"Mitigate risks with thorough due diligence.","zh-TW":"通過徹底的盡職調查緩解風險。"}]', 'phrasal verb'),
('monetize assets', '將資產變現；貨幣化資產', 'to convert assets or capabilities into revenue', '[{"en":"We found new ways to monetize our data assets.","zh-TW":"我們找到了將數據資產變現的新方法。"},{"en":"Monetize your content with subscriptions and sponsorships.","zh-TW":"通過訂閱和贊助將你的內容貨幣化。"}]', 'phrasal verb'),
('move toward', '朝向；逐步走向', 'to progress in the direction of a particular state or goal', '[{"en":"We are moving toward a subscription-based model.","zh-TW":"我們正在逐步走向訂閱制模式。"},{"en":"Move toward a data-driven culture step by step.","zh-TW":"逐步走向數據驅動的文化。"}]', 'phrasal verb'),
('negotiate in good faith', '誠信談判；真誠協商', 'to negotiate honestly and sincerely, without deceptive tactics', '[{"en":"We always negotiate in good faith with our partners.","zh-TW":"我們始終與合作夥伴誠信談判。"},{"en":"Negotiating in good faith builds long-term trust.","zh-TW":"真誠協商建立了長期信任。"}]', 'phrasal verb'),
('act with urgency', '以緊迫感行動；緊迫應對', 'to respond with speed and importance proportional to the situation', '[{"en":"Act with urgency when customer satisfaction is at risk.","zh-TW":"當客戶滿意度面臨風險時以緊迫感行動。"},{"en":"Act with urgency to capitalize on the market window.","zh-TW":"緊迫應對以把握市場機會窗口。"}]', 'expression'),
('across functional lines', '跨越職能界限；橫跨各部門', 'spanning multiple departments or functional areas', '[{"en":"Effective innovation requires collaboration across functional lines.","zh-TW":"有效的創新需要跨越職能界限的協作。"},{"en":"The project team worked across functional lines to deliver.","zh-TW":"專案團隊跨越各部門界限進行交付。"}]', 'prepositional phrase'),
('after the fact', '事後；事情發生後', 'after the event or situation has already occurred', '[{"en":"Don''t wait to discover problems after the fact.","zh-TW":"不要等到事後才發現問題。"},{"en":"We''ll review the decision after the fact with data.","zh-TW":"我們將在事後用數據審查這個決定。"}]', 'prepositional phrase'),
('along the lines of', '類似於；沿著…的思路', 'similar to or following the general idea of something', '[{"en":"We''re looking for something along the lines of their model.","zh-TW":"我們正在尋找類似於他們模式的東西。"},{"en":"Think along the lines of a subscription tier system.","zh-TW":"沿著訂閱等級系統的思路思考。"}]', 'prepositional phrase'),
('as a benchmark', '作為基準；以…為參照', 'using something as a reference point for comparison or evaluation', '[{"en":"Use industry average margins as a benchmark.","zh-TW":"以行業平均利潤率作為基準。"},{"en":"As a benchmark the top performer converts at 20%.","zh-TW":"以頂尖表現者為基準，轉換率達到20%。"}]', 'prepositional phrase'),
('as a fallback', '作為備案；備用方案', 'as an alternative option if the primary plan fails', '[{"en":"Keep a contingency plan as a fallback.","zh-TW":"保留一個備案作為應急方案。"},{"en":"As a fallback we can delay the launch by one quarter.","zh-TW":"作為備案我們可以將發布推遲一個季度。"}]', 'prepositional phrase'),
('as the situation demands', '視情況所需；因應情況需要', 'responding appropriately to whatever the circumstances require', '[{"en":"Be ready to pivot as the situation demands.","zh-TW":"準備好視情況所需進行轉向。"},{"en":"As the situation demands we scale up or down quickly.","zh-TW":"因應情況需要我們迅速擴大或縮小規模。"}]', 'prepositional phrase'),
('at a moment''s notice', '隨時；一聲令下就可以', 'with very little or no advance warning', '[{"en":"Our response team can deploy at a moment''s notice.","zh-TW":"我們的響應團隊可以隨時部署。"},{"en":"Be ready to present at a moment''s notice to senior leadership.","zh-TW":"隨時準備好向高層管理人員做演示。"}]', 'prepositional phrase'),
('at the bottom line', '歸結到最後；最終而言', 'ultimately; when all considerations are weighed', '[{"en":"At the bottom line we need to show profit.","zh-TW":"歸結到最後我們需要展示利潤。"},{"en":"At the bottom line client satisfaction drives retention.","zh-TW":"最終而言客戶滿意度推動留存率。"}]', 'prepositional phrase'),
('at the discretion of', '由…決定；依…的判斷', 'left to the judgment or choice of a specific person or authority', '[{"en":"Bonuses are awarded at the discretion of the manager.","zh-TW":"獎金由經理決定發放。"},{"en":"The terms are flexible at the discretion of both parties.","zh-TW":"條款依雙方的判斷靈活調整。"}]', 'prepositional phrase'),
('at the intersection of', '在…的交叉點上；處於…兩者之間', 'at the point where two or more fields, trends, or ideas meet', '[{"en":"Our product lives at the intersection of health and technology.","zh-TW":"我們的產品處於健康與技術的交叉點上。"},{"en":"Innovation often happens at the intersection of disciplines.","zh-TW":"創新往往發生在學科的交叉點上。"}]', 'prepositional phrase'),
('at this juncture', '在此關鍵時刻；此時此刻', 'at this particular important moment in time', '[{"en":"At this juncture the board must make a clear decision.","zh-TW":"在此關鍵時刻董事會必須做出明確的決定。"},{"en":"At this juncture any delay would be costly.","zh-TW":"此時此刻任何延誤都會造成代價。"}]', 'prepositional phrase'),
('at your earliest convenience', '方便時儘快；在你方便的最早時間', 'as soon as it is possible for you to do something', '[{"en":"Please reply at your earliest convenience.","zh-TW":"請方便時儘快回覆。"},{"en":"Submit the form at your earliest convenience to secure your spot.","zh-TW":"請在方便時儘快提交表格以確保你的席位。"}]', 'prepositional phrase');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('barring unforeseen circumstances', '除非有意外情況；若無意外', 'unless something unexpected happens to prevent it', '[{"en":"Barring unforeseen circumstances the project will launch on time.","zh-TW":"若無意外這個專案將按時發布。"},{"en":"Barring unforeseen circumstances we should close the deal this week.","zh-TW":"除非有意外情況，我們本週應該可以完成交易。"}]', 'prepositional phrase'),
('based on merit', '以能力為依據；依靠實力', 'judged or decided according to performance or ability', '[{"en":"All promotions are decided based on merit.","zh-TW":"所有晉升都以能力為依據決定。"},{"en":"We hire and promote based on merit not seniority.","zh-TW":"我們依靠實力而不是資歷進行招聘和晉升。"}]', 'prepositional phrase'),
('below market rate', '低於市場價格', 'priced or compensated at a level lower than the average market level', '[{"en":"They accepted the deal at below market rate to enter the territory.","zh-TW":"他們以低於市場價格接受了這筆交易以進入該市場。"},{"en":"Offering below market rate risks attracting lower-quality hires.","zh-TW":"提供低於市場的薪資有吸引低品質人才的風險。"}]', 'prepositional phrase'),
('between the lines', '話中有話；言外之意', 'the implied or hidden meaning behind what is written or said', '[{"en":"You need to read between the lines of their proposal.","zh-TW":"你需要看出他們提案的言外之意。"},{"en":"There''s something between the lines — ask them directly.","zh-TW":"話中有話——直接問他們。"}]', 'prepositional phrase'),
('bring under control', '控制住；加以管控', 'to manage or restrain something that was difficult to handle', '[{"en":"Management worked to bring costs under control.","zh-TW":"管理層努力控制住了成本。"},{"en":"Bring the project timeline under control before it derails.","zh-TW":"在專案脫軌之前把時間表控制住。"}]', 'phrasal verb'),
('broker a deal', '促成交易；中介達成協議', 'to negotiate and arrange a deal between parties', '[{"en":"The investment bank brokered a deal between the two firms.","zh-TW":"投資銀行促成了兩家公司之間的交易。"},{"en":"She brokered a deal that satisfied all stakeholders.","zh-TW":"她促成了一筆令所有利益相關者滿意的交易。"}]', 'phrasal verb'),
('build consensus', '建立共識；達成一致意見', 'to develop agreement among multiple people or groups', '[{"en":"Build consensus before announcing the strategic change.","zh-TW":"在宣布策略性變化之前建立共識。"},{"en":"She built consensus through individual conversations.","zh-TW":"她通過個人談話建立了共識。"}]', 'phrasal verb'),
('build momentum', '積累動力；建立勢頭', 'to gradually increase the speed or strength of progress', '[{"en":"Build momentum with quick wins before the big push.","zh-TW":"在大力推進之前通過快速勝利積累動力。"},{"en":"The campaign built momentum through social media.","zh-TW":"這個活動通過社交媒體建立了勢頭。"}]', 'phrasal verb'),
('build rapport', '建立融洽關係；拉近距離', 'to establish a friendly and trusting relationship', '[{"en":"Build rapport with clients before pitching.","zh-TW":"在推介前與客戶建立融洽關係。"},{"en":"She builds rapport quickly by genuinely listening.","zh-TW":"她通過真正傾聽快速拉近距離。"}]', 'phrasal verb'),
('buy time', '爭取時間；拖延（以便準備）', 'to delay something intentionally to gain more time', '[{"en":"We bought time by requesting a contract extension.","zh-TW":"我們通過請求合約延期來爭取時間。"},{"en":"Buying time is only useful if you use it wisely.","zh-TW":"爭取到的時間只有明智使用才有價值。"}]', 'phrasal verb'),
('capture attention', '吸引注意力；抓住眼球', 'to attract and hold someone''s interest or focus', '[{"en":"The new packaging captures attention on retail shelves.","zh-TW":"新包裝在零售貨架上吸引了注意力。"},{"en":"Capture attention in the first five seconds of your pitch.","zh-TW":"在推介的前五秒抓住眼球。"}]', 'phrasal verb'),
('capture market share', '搶佔市場份額', 'to gain a percentage of the total sales in a market', '[{"en":"The new pricing strategy helped capture market share.","zh-TW":"新定價策略有助於搶佔市場份額。"},{"en":"We captured 5% market share in the first year.","zh-TW":"我們在第一年就搶佔了5%的市場份額。"}]', 'phrasal verb'),
('change the narrative', '改變敘事；改變輿論走向', 'to alter the story or perception surrounding a situation', '[{"en":"We need to change the narrative after the PR crisis.","zh-TW":"在公關危機後我們需要改變敘事。"},{"en":"The new strategy changed the narrative from decline to growth.","zh-TW":"新策略將敘事從衰退轉變為增長。"}]', 'expression'),
('circle the wagons', '聚集自衛；抱緊成一團應對危機', 'to gather together to defend against threats', '[{"en":"The company circled the wagons after the media attack.","zh-TW":"媒體攻擊後公司聚集起來進行自衛。"},{"en":"Circle the wagons and focus on your core strengths.","zh-TW":"抱緊成一團應對危機，專注於核心優勢。"}]', 'expression'),
('come in under budget', '預算有結餘；花費低於預算', 'to complete a project while spending less than the allocated budget', '[{"en":"The team came in under budget by 10% this quarter.","zh-TW":"這個季度團隊預算有10%的結餘。"},{"en":"Coming in under budget builds trust with leadership.","zh-TW":"預算有結餘建立了與領導層的信任。"}]', 'expression'),
('competitive bidding', '競爭性投標；公開競標', 'a process where multiple vendors submit bids and the best one wins', '[{"en":"We use competitive bidding for all major contracts.","zh-TW":"我們對所有重大合約使用競爭性投標。"},{"en":"Competitive bidding ensures we get the best value.","zh-TW":"競爭性投標確保我們獲得最佳價值。"}]', 'business idiom'),
('compound interest effect', '複利效應；積累效應', 'the accelerating power of gains that build upon previous gains over time', '[{"en":"Small daily improvements create a compound interest effect.","zh-TW":"每日的小進步會產生積累效應。"},{"en":"The compound interest effect explains why consistent marketing wins.","zh-TW":"複利效應解釋了為什麼持續行銷最終獲勝。"}]', 'business idiom'),
('control the narrative', '掌控敘事；主導輿論', 'to manage how a story or situation is perceived and discussed', '[{"en":"Control the narrative by communicating proactively.","zh-TW":"通過主動溝通掌控敘事。"},{"en":"Brands that control the narrative during crises recover faster.","zh-TW":"在危機中主導輿論的品牌恢復更快。"}]', 'expression'),
('core values alignment', '核心價值觀一致；價值觀契合', 'the match between a person''s or organization''s values and those of a partner', '[{"en":"Core values alignment is essential in long-term partnerships.","zh-TW":"核心價值觀一致在長期合作中至關重要。"},{"en":"We screen candidates for core values alignment.","zh-TW":"我們篩選與核心價值觀契合的候選人。"}]', 'business idiom'),
('cost-benefit analysis', '成本效益分析', 'a systematic comparison of the costs and benefits of a decision or action', '[{"en":"We ran a cost-benefit analysis before approving the investment.","zh-TW":"在批准投資之前我們進行了成本效益分析。"},{"en":"A cost-benefit analysis guides smarter resource allocation.","zh-TW":"成本效益分析指導更智慧的資源分配。"}]', 'business idiom'),
('crisis management', '危機管理', 'the process of handling unexpected negative events to minimize damage', '[{"en":"The team activated their crisis management protocol immediately.","zh-TW":"團隊立即啟動了危機管理協議。"},{"en":"Effective crisis management preserves brand reputation.","zh-TW":"有效的危機管理保護了品牌聲譽。"}]', 'business idiom'),
('cross the finish line', '完成目標；達到終點', 'to complete a goal or project successfully', '[{"en":"We''re almost there — just need to cross the finish line.","zh-TW":"我們幾乎到了——只需完成最後的目標。"},{"en":"Help the team cross the finish line by removing blockers.","zh-TW":"通過移除阻礙幫助團隊達到終點。"}]', 'expression'),
('data-backed decision', '有數據支撐的決策', 'a decision supported by evidence from data analysis', '[{"en":"Every budget allocation should be a data-backed decision.","zh-TW":"每個預算分配都應該是有數據支撐的決策。"},{"en":"Data-backed decisions reduce costly guesswork.","zh-TW":"有數據支撐的決策減少了代價高昂的猜測。"}]', 'business idiom'),
('dead on arrival', '一開始就失敗的；從一開始就沒希望的', 'doomed to fail from the very start', '[{"en":"The proposal was dead on arrival without executive support.","zh-TW":"沒有高層支持，這個提案從一開始就沒有希望。"},{"en":"A product without customer research is often dead on arrival.","zh-TW":"沒有客戶研究的產品往往從一開始就失敗。"}]', 'expression'),
('deliver value', '創造價值；提供價值', 'to provide tangible benefits or results that meet or exceed expectations', '[{"en":"Our mission is to deliver value at every customer touchpoint.","zh-TW":"我們的使命是在每個客戶接觸點創造價值。"},{"en":"Delivering value consistently builds brand loyalty.","zh-TW":"持續提供價值建立了品牌忠誠度。"}]', 'expression'),
('design thinking', '設計思維', 'a human-centered approach to innovation that focuses on empathy and iteration', '[{"en":"We applied design thinking to redesign the customer journey.","zh-TW":"我們應用設計思維重新設計了客戶旅程。"},{"en":"Design thinking leads to more user-friendly solutions.","zh-TW":"設計思維帶來了更易用的解決方案。"}]', 'business idiom'),
('develop a thick skin', '培養抗壓能力；學會不怕批評', 'to become less sensitive to criticism or setbacks', '[{"en":"In sales you need to develop a thick skin for rejections.","zh-TW":"在銷售工作中你需要培養對拒絕的抗壓能力。"},{"en":"Develop a thick skin while still staying open to growth.","zh-TW":"培養抗壓能力的同時保持對成長的開放態度。"}]', 'expression'),
('dial in', '調整到最佳狀態；精確調整', 'to fine-tune or optimize something to the right level', '[{"en":"We need to dial in the pricing before the launch.","zh-TW":"發布前我們需要將定價調整到最佳狀態。"},{"en":"Dial in the messaging to resonate with the target segment.","zh-TW":"精確調整信息以引起目標細分市場的共鳴。"}]', 'phrasal verb'),
('differentiate or die', '差異化或被淘汰', 'the business imperative to stand out from competitors or face failure', '[{"en":"In a crowded market it''s differentiate or die.","zh-TW":"在擁擠的市場中就是差異化或被淘汰。"},{"en":"The brand understood the differentiate or die reality.","zh-TW":"品牌理解了差異化或被淘汰的現實。"}]', 'expression'),
('digital-first', '數位優先', 'prioritizing digital channels and solutions in strategy and operations', '[{"en":"Our digital-first strategy reaches younger consumers effectively.","zh-TW":"我們的數位優先策略有效地接觸了年輕消費者。"},{"en":"Going digital-first reduced our operational costs by 20%.","zh-TW":"採用數位優先使我們的運營成本降低了20%。"}]', 'business idiom'),
('do a 180', '完全改變方向；大逆轉', 'to completely reverse one''s position or approach', '[{"en":"The company did a 180 on its remote work policy.","zh-TW":"公司在遠端工作政策上完全改變了方向。"},{"en":"Doing a 180 too quickly can confuse stakeholders.","zh-TW":"大逆轉太快可能會讓利益相關者感到困惑。"}]', 'expression'),
('dominant market position', '市場主導地位', 'when one company has a very strong hold on a market', '[{"en":"Amazon maintains a dominant market position in e-commerce.","zh-TW":"亞馬遜在電子商務中保持市場主導地位。"},{"en":"A dominant market position provides pricing power.","zh-TW":"市場主導地位提供了定價能力。"}]', 'business idiom'),
('double-edged sword', '雙刃劍；有利有弊', 'something that has both benefits and drawbacks at the same time', '[{"en":"Rapid expansion is a double-edged sword.","zh-TW":"快速擴張是一把雙刃劍。"},{"en":"Transparency can be a double-edged sword in negotiations.","zh-TW":"透明度在談判中可以是一把雙刃劍。"}]', 'expression'),
('drill down into', '深入細節；逐層分析', 'to examine or analyze something at a more detailed level', '[{"en":"Drill down into the sales data by region.","zh-TW":"深入細節按地區分析銷售數據。"},{"en":"We drilled down into the customer complaints to find the root cause.","zh-TW":"我們逐層分析了客戶投訴以找到根本原因。"}]', 'phrasal verb'),
('drop everything', '放下一切；立即處理', 'to stop all other activities to focus on something urgent', '[{"en":"When the server went down everyone dropped everything.","zh-TW":"伺服器崩潰時所有人都放下了一切。"},{"en":"Drop everything and respond to the key client''s request.","zh-TW":"放下一切立即回應重要客戶的請求。"}]', 'expression'),
('drive change', '推動變革；推動改變', 'to be the catalyst for significant organizational or behavioral transformation', '[{"en":"Leadership must drive change from the top.","zh-TW":"領導層必須從頂層推動變革。"},{"en":"Data-driven insights can drive change in marketing strategy.","zh-TW":"數據驅動的洞察可以推動行銷策略的改變。"}]', 'phrasal verb'),
('drive efficiency', '提高效率；推動效率提升', 'to improve the ratio of output to input in operations', '[{"en":"Automation drives efficiency across the supply chain.","zh-TW":"自動化在整個供應鏈中提高了效率。"},{"en":"Drive efficiency by standardizing repetitive processes.","zh-TW":"通過標準化重複流程推動效率提升。"}]', 'phrasal verb'),
('earn trust', '贏得信任', 'to build confidence and credibility through consistent behavior', '[{"en":"We earned trust by delivering on every promise.","zh-TW":"我們通過兌現每一個承諾贏得了信任。"},{"en":"Earning trust takes time but can be lost instantly.","zh-TW":"贏得信任需要時間，但可以在瞬間失去。"}]', 'phrasal verb'),
('elevate performance', '提升表現；提高業績', 'to raise the level of results or output beyond current standards', '[{"en":"Coaching elevates performance across the team.","zh-TW":"輔導提升了整個團隊的表現。"},{"en":"Elevate performance by setting ambitious but realistic targets.","zh-TW":"通過設定雄心勃勃但現實的目標提升業績。"}]', 'phrasal verb'),
('engage stakeholders', '與利益相關者互動；吸引利益相關者參與', 'to involve or communicate with all relevant parties', '[{"en":"Engage stakeholders early to prevent resistance later.","zh-TW":"早期與利益相關者互動以防止後來的阻力。"},{"en":"We engage stakeholders through regular updates and feedback.","zh-TW":"我們通過定期更新和反饋吸引利益相關者參與。"}]', 'phrasal verb'),
('escalate quickly', '迅速升級；快速上報', 'to move an issue to a higher level of authority without delay', '[{"en":"Escalate quickly when a client issue risks the relationship.","zh-TW":"當客戶問題危及關係時迅速上報。"},{"en":"Don''t hesitate to escalate quickly to prevent larger problems.","zh-TW":"不要猶豫，迅速升級以防止更大的問題。"}]', 'phrasal verb'),
('execute flawlessly', '完美執行；無誤落實', 'to carry out a plan with precision and without errors', '[{"en":"The team executed the campaign flawlessly.","zh-TW":"團隊完美地執行了這次活動。"},{"en":"A great strategy counts for nothing if not executed flawlessly.","zh-TW":"如果沒有完美執行，再好的策略也毫無用處。"}]', 'phrasal verb'),
('expand footprint', '擴大業務範圍；擴展版圖', 'to increase the geographic or market presence of a business', '[{"en":"We plan to expand our footprint in Southeast Asia.","zh-TW":"我們計劃在東南亞擴大業務範圍。"},{"en":"Expanding your digital footprint increases brand awareness.","zh-TW":"擴展數位版圖增加了品牌知名度。"}]', 'phrasal verb'),
('experiment with', '嘗試；試驗', 'to try out new methods or ideas to see how they perform', '[{"en":"We experimented with dynamic pricing to optimize revenue.","zh-TW":"我們嘗試了動態定價以優化收益。"},{"en":"Experiment with different formats to find what resonates.","zh-TW":"試驗不同格式以找到什麼能引起共鳴。"}]', 'phrasal verb'),
('face down', '直面；應對；克服', 'to confront and overcome a challenging situation or opponent', '[{"en":"The CEO faced down intense pressure from shareholders.","zh-TW":"執行長直面了股東的強大壓力。"},{"en":"Face down the competition with better innovation.","zh-TW":"以更好的創新應對競爭。"}]', 'phrasal verb'),
('field test', '現場測試；實地驗證', 'to test a product or idea in real-world conditions', '[{"en":"We field tested the app with 200 users before launch.","zh-TW":"發布前我們與200位用戶進行了現場測試。"},{"en":"Field testing reveals issues that lab testing misses.","zh-TW":"現場測試揭示了實驗室測試遺漏的問題。"}]', 'phrasal verb'),
('fine-tune', '微調；精確調整', 'to make small precise adjustments to improve performance', '[{"en":"We fine-tuned the onboarding flow based on user feedback.","zh-TW":"我們根據用戶反饋對入職流程進行了微調。"},{"en":"Fine-tune your pitch for each specific client.","zh-TW":"針對每個具體客戶精確調整你的推介。"}]', 'phrasal verb'),
('focus group', '焦點小組；用戶研究小組', 'a small group of people whose opinions are used to represent a wider market', '[{"en":"We conducted a focus group before the rebrand.","zh-TW":"在品牌重塑之前我們進行了焦點小組研究。"},{"en":"Focus group feedback shaped the product roadmap.","zh-TW":"焦點小組反饋塑造了產品路線圖。"}]', 'business idiom'),
('foothold in', '在…中站穩腳跟；進入的立足點', 'an initial position in a new market or area that allows further development', '[{"en":"Winning that client gave us a foothold in the sector.","zh-TW":"贏得那個客戶讓我們在該行業站穩了腳跟。"},{"en":"Establish a foothold in the Asian market within two years.","zh-TW":"在兩年內在亞洲市場建立立足點。"}]', 'expression'),
('forecast accurately', '準確預測；精確預報', 'to predict future performance with a high degree of precision', '[{"en":"It''s difficult to forecast accurately in a volatile market.","zh-TW":"在波動的市場中很難準確預測。"},{"en":"We use AI to forecast more accurately.","zh-TW":"我們使用AI進行更精確的預測。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('forge ahead', '勇往直前；繼續推進', 'to continue moving forward with determination despite challenges', '[{"en":"We forged ahead with the launch despite supply constraints.","zh-TW":"儘管有供應限制我們仍勇往直前推進了發布。"},{"en":"Forge ahead with innovation even when the path is uncertain.","zh-TW":"即使道路不確定也要繼續推進創新。"}]', 'phrasal verb'),
('foster innovation', '培育創新；促進創新', 'to create conditions that encourage new ideas and approaches', '[{"en":"We foster innovation through cross-functional workshops.","zh-TW":"我們通過跨職能工作坊培育創新。"},{"en":"Foster innovation by tolerating thoughtful failure.","zh-TW":"通過容忍有意義的失敗促進創新。"}]', 'phrasal verb'),
('fuel growth', '推動增長；促進增長', 'to provide the resources or momentum needed for expansion', '[{"en":"The new funding will fuel growth into new markets.","zh-TW":"新的融資將推動進入新市場的增長。"},{"en":"Product innovation continues to fuel growth quarter over quarter.","zh-TW":"產品創新持續推動著季度增長。"}]', 'phrasal verb'),
('gain a foothold', '站穩腳跟；取得立足點', 'to establish a small but stable position in a new market or area', '[{"en":"We gained a foothold in the European market through a local partner.","zh-TW":"我們通過當地合作夥伴在歐洲市場站穩了腳跟。"},{"en":"Gain a foothold early before the market consolidates.","zh-TW":"在市場整合之前儘早取得立足點。"}]', 'phrasal verb'),
('garner support', '獲得支持；爭取支持', 'to collect or attract backing, approval, or endorsement', '[{"en":"The initiative garnered support from all departments.","zh-TW":"這個計劃從所有部門獲得了支持。"},{"en":"Garner support early to avoid obstacles later.","zh-TW":"早期爭取支持以避免後來的障礙。"}]', 'phrasal verb'),
('get sign-off', '獲得批准；取得核可', 'to obtain formal approval from a person in authority', '[{"en":"Get sign-off from legal before sending the contract.","zh-TW":"在發送合約之前獲得法律部門的批准。"},{"en":"She got sign-off from the CFO for the extra budget.","zh-TW":"她從首席財務官那裡取得了額外預算的核可。"}]', 'phrasal verb'),
('give the benefit of the doubt', '給予信任；暫時相信對方', 'to treat someone as honest or capable despite uncertainty', '[{"en":"Give new hires the benefit of the doubt during the first month.","zh-TW":"在第一個月給新員工信任的機會。"},{"en":"Give the client the benefit of the doubt when payment is late.","zh-TW":"當付款延誤時暫時相信客戶。"}]', 'expression'),
('go the distance', '堅持到底；完成全程', 'to see something through to the end despite difficulty', '[{"en":"We will go the distance to ensure client success.","zh-TW":"我們將堅持到底確保客戶成功。"},{"en":"Only those who go the distance earn sustainable success.","zh-TW":"只有堅持到底的人才能獲得可持續的成功。"}]', 'expression'),
('govern by committee', '委員會式管理；集體決策', 'to make decisions through a group rather than individually', '[{"en":"Governing by committee slows down decision-making.","zh-TW":"委員會式管理減慢了決策速度。"},{"en":"Balance governance by committee with empowered individuals.","zh-TW":"在集體決策與授權個人之間取得平衡。"}]', 'expression'),
('grind to a halt', '停擺；陷入停頓', 'to stop completely after slowing down gradually', '[{"en":"The supply disruption brought production to a grind to a halt.","zh-TW":"供應中斷使生產陷入停頓。"},{"en":"Without capital the startup ground to a halt.","zh-TW":"沒有資金這家新創公司完全停擺了。"}]', 'expression'),
('grounded in reality', '立足現實；腳踏實地', 'based on practical facts rather than wishful thinking', '[{"en":"Keep your projections grounded in reality.","zh-TW":"讓你的預測立足現實。"},{"en":"Grounded in reality our forecast is conservative but achievable.","zh-TW":"腳踏實地我們的預測是保守但可實現的。"}]', 'expression'),
('hands on deck', '全員就位；緊急需要人手', 'all available people needed to help', '[{"en":"We need all hands on deck for the data migration.","zh-TW":"數據遷移需要全員就位。"},{"en":"When the system crashed it was all hands on deck.","zh-TW":"系統崩潰時需要緊急全員就位。"}]', 'expression'),
('have a game-changer', '有改變遊戲規則的優勢；有關鍵突破', 'to possess something that significantly changes competitive dynamics', '[{"en":"We have a game-changer with our new AI feature.","zh-TW":"我們擁有改變遊戲規則的新AI功能。"},{"en":"Having a game-changer creates first-mover advantage.","zh-TW":"擁有關鍵突破創造了先發優勢。"}]', 'expression'),
('heavy hitter', '重量級人物；有影響力的人或公司', 'a very important or influential person or organization', '[{"en":"We brought in a heavy hitter from the industry to lead negotiations.","zh-TW":"我們引進了行業重量級人物來主導談判。"},{"en":"Landing a heavy hitter client validates your product.","zh-TW":"拿下有影響力的客戶驗證了你的產品。"}]', 'expression'),
('high-touch service', '高度個性化服務；密集互動服務', 'a service approach that involves frequent, personal interaction', '[{"en":"Enterprise clients expect high-touch service.","zh-TW":"企業客戶期望高度個性化服務。"},{"en":"High-touch service builds loyalty in premium segments.","zh-TW":"密集互動服務在高端細分市場建立了忠誠度。"}]', 'business idiom'),
('hire for attitude train for skill', '招有態度的人再培訓技能', 'the belief that attitude matters more than existing skills in hiring', '[{"en":"Our approach is hire for attitude train for skill.","zh-TW":"我們的方法是招有態度的人再培訓技能。"},{"en":"Hire for attitude train for skill produces more loyal employees.","zh-TW":"招有態度的人再培訓技能產生了更忠誠的員工。"}]', 'expression'),
('hold harmless', '免責；不追究責任', 'to protect someone from legal liability or losses', '[{"en":"The contract includes a hold harmless clause for third-party damages.","zh-TW":"合約中包含了對第三方損害的免責條款。"},{"en":"Hold harmless agreements protect service providers.","zh-TW":"免責協議保護了服務提供者。"}]', 'expression'),
('hold to account', '追究責任；問責', 'to require someone to explain or take responsibility for their actions', '[{"en":"Managers are held to account for team performance.","zh-TW":"經理要對團隊績效負責。"},{"en":"Hold vendors to account when they miss SLA targets.","zh-TW":"當供應商未達到服務水準協議目標時追究其責任。"}]', 'expression'),
('horizon scanning', '前景掃描；未來趨勢探查', 'the systematic review of potential future developments and trends', '[{"en":"Horizon scanning helps us anticipate market shifts.","zh-TW":"前景掃描幫助我們預測市場轉變。"},{"en":"Include horizon scanning in your annual strategic review.","zh-TW":"在年度策略審查中包含前景掃描。"}]', 'business idiom'),
('house in order', '把自己的問題解決好；整頓內部', 'to sort out one''s own affairs or internal problems before addressing others', '[{"en":"Get your house in order before entering new markets.","zh-TW":"在進入新市場之前整頓好內部問題。"},{"en":"The CEO focused on getting the house in order after the merger.","zh-TW":"合併後執行長專注於整頓內部。"}]', 'expression'),
('human capital', '人力資本', 'the skills, knowledge, and experience of employees as an economic resource', '[{"en":"Investing in human capital is investing in the company''s future.","zh-TW":"投資人力資本就是投資公司的未來。"},{"en":"Human capital development is a priority in our HR strategy.","zh-TW":"人力資本發展是我們人力資源策略的優先事項。"}]', 'business idiom'),
('identify gaps', '識別差距；找出缺口', 'to find missing areas or weaknesses in a plan, process, or market', '[{"en":"We identified gaps in the current product offering.","zh-TW":"我們識別了當前產品組合中的差距。"},{"en":"Identify gaps in your team''s capabilities through assessment.","zh-TW":"通過評估找出團隊能力中的缺口。"}]', 'phrasal verb'),
('impact-driven', '以影響力為導向；注重影響力', 'focused on creating measurable positive outcomes', '[{"en":"Our impact-driven culture attracts mission-aligned talent.","zh-TW":"我們以影響力為導向的文化吸引了有使命感的人才。"},{"en":"Investors value impact-driven businesses in today''s market.","zh-TW":"今天的市場中投資者重視注重影響力的業務。"}]', 'business idiom'),
('impossible ask', '不合理的要求；過分的請求', 'a request or demand that cannot reasonably be fulfilled', '[{"en":"Delivering in 24 hours is an impossible ask without more staff.","zh-TW":"在沒有更多員工的情況下24小時內交付是不合理的要求。"},{"en":"Explain why a request is an impossible ask rather than just refusing.","zh-TW":"解釋為什麼一個請求是不合理的而不是簡單拒絕。"}]', 'expression'),
('in a vacuum', '孤立地；脫離背景地', 'without considering the surrounding context or related factors', '[{"en":"No business decision exists in a vacuum.","zh-TW":"沒有商業決策是孤立存在的。"},{"en":"Don''t evaluate this in a vacuum — consider the broader market.","zh-TW":"不要脫離背景評估這個——考慮更廣泛的市場。"}]', 'prepositional phrase'),
('in every sense of the word', '從各種意義上說；完全地', 'completely and in all respects', '[{"en":"She is a leader in every sense of the word.","zh-TW":"從各種意義上說她是一位領導者。"},{"en":"This was a successful launch in every sense of the word.","zh-TW":"從各種意義上說這是一次成功的發布。"}]', 'prepositional phrase'),
('in flux', '處於變動中；不穩定', 'in a state of continuous change or uncertainty', '[{"en":"The regulatory landscape is in flux.","zh-TW":"監管環境正處於變動中。"},{"en":"Our strategy is in flux as we respond to new market data.","zh-TW":"我們的策略因應新市場數據而不穩定。"}]', 'prepositional phrase'),
('in good standing', '信譽良好；帳戶正常', 'meeting all requirements or obligations and in a satisfactory position', '[{"en":"All vendors must be in good standing to bid.","zh-TW":"所有供應商必須信譽良好才能投標。"},{"en":"We ensure our accounts are in good standing with regulators.","zh-TW":"我們確保我們的帳戶與監管機構保持正常狀態。"}]', 'prepositional phrase'),
('in lock-step', '步調一致；完全協調地', 'moving or progressing in complete agreement or simultaneously', '[{"en":"The two departments moved in lock-step on the launch.","zh-TW":"兩個部門在發布上步調一致。"},{"en":"Stay in lock-step with your partners to avoid misalignment.","zh-TW":"與合作夥伴保持步調一致以避免不一致。"}]', 'prepositional phrase'),
('in real time', '即時地；實時地', 'happening immediately as events unfold', '[{"en":"We monitor customer feedback in real time.","zh-TW":"我們即時監控客戶反饋。"},{"en":"In real time adjustments are possible with our dashboards.","zh-TW":"使用我們的儀表板可以進行實時調整。"}]', 'prepositional phrase'),
('in short order', '迅速地；短時間內', 'quickly and without delay', '[{"en":"The team resolved the issue in short order.","zh-TW":"團隊迅速解決了這個問題。"},{"en":"Deliver a prototype in short order to show momentum.","zh-TW":"在短時間內交付原型以展示勢頭。"}]', 'prepositional phrase'),
('in the best interest of', '符合…的最大利益', 'for the benefit or advantage of a particular person or group', '[{"en":"All decisions are made in the best interest of our clients.","zh-TW":"所有決策都符合我們客戶的最大利益。"},{"en":"Act in the best interest of all stakeholders.","zh-TW":"以所有利益相關者的最大利益行事。"}]', 'prepositional phrase'),
('in the same vein', '以同樣的方式；沿著同樣的思路', 'in the same style or following the same idea as before', '[{"en":"In the same vein we should cut costs in operations too.","zh-TW":"以同樣的方式，我們也應該削減運營成本。"},{"en":"In the same vein the marketing team needs to streamline.","zh-TW":"沿著同樣的思路行銷團隊也需要精簡。"}]', 'prepositional phrase'),
('in the wings', '待命中；即將登場', 'waiting in readiness to step in when needed', '[{"en":"We have a new product line waiting in the wings.","zh-TW":"我們有一條新產品線即將登場。"},{"en":"Keep a successor candidate in the wings for key roles.","zh-TW":"為關鍵職位準備待命的繼任候選人。"}]', 'prepositional phrase'),
('income statement', '損益表', 'a financial statement showing revenues, costs, and profits over a period', '[{"en":"The income statement showed a 15% increase in net profit.","zh-TW":"損益表顯示淨利潤增長了15%。"},{"en":"Analyze the income statement before the investor meeting.","zh-TW":"在投資者會議前分析損益表。"}]', 'business idiom'),
('incremental improvement', '漸進式改進；逐步提升', 'making small continuous improvements rather than large leaps', '[{"en":"Incremental improvement compounds over time into significant gains.","zh-TW":"漸進式改進隨時間積累成顯著的收益。"},{"en":"Focus on incremental improvement when radical change is too risky.","zh-TW":"當激進變革風險太高時專注於漸進式改進。"}]', 'business idiom'),
('industry benchmark', '行業基準；行業標準', 'a standard or reference point used to compare performance in an industry', '[{"en":"Our NPS score exceeds the industry benchmark by 20 points.","zh-TW":"我們的NPS分數超過行業基準20分。"},{"en":"Set targets using industry benchmarks as a reference.","zh-TW":"以行業基準作為參考設定目標。"}]', 'business idiom'),
('industry disruptor', '行業顛覆者', 'a company or product that fundamentally changes how an industry operates', '[{"en":"The startup emerged as an industry disruptor in logistics.","zh-TW":"這家新創公司在物流業崛起為行業顛覆者。"},{"en":"Industry disruptors create new market categories.","zh-TW":"行業顛覆者創造了新的市場類別。"}]', 'business idiom'),
('information asymmetry', '資訊不對稱', 'when one party in a transaction has more or better information than the other', '[{"en":"Information asymmetry often gives negotiators an advantage.","zh-TW":"資訊不對稱往往給談判者帶來優勢。"},{"en":"Transparency reduces information asymmetry in markets.","zh-TW":"透明度降低了市場中的資訊不對稱。"}]', 'business idiom'),
('innovation pipeline', '創新管道；待開發的創新項目', 'a structured set of ideas or projects being developed for future use', '[{"en":"A healthy innovation pipeline ensures long-term growth.","zh-TW":"健康的創新管道確保了長期增長。"},{"en":"Our innovation pipeline includes 12 new products.","zh-TW":"我們的創新管道包含12個新產品。"}]', 'business idiom'),
('input from stakeholders', '利益相關者的意見；各方投入', 'feedback or contributions from relevant parties involved in a process', '[{"en":"We gathered input from stakeholders before finalizing the plan.","zh-TW":"在最終確定計劃之前我們收集了利益相關者的意見。"},{"en":"Input from stakeholders improves the quality of decisions.","zh-TW":"利益相關者的意見提高了決策品質。"}]', 'expression'),
('intrapreneur', '內部創業家；公司內的創業者', 'an employee who develops new ventures or ideas within an organization', '[{"en":"We encourage intrapreneurs to test ideas within the company.","zh-TW":"我們鼓勵員工作為內部創業家在公司內測試想法。"},{"en":"Intrapreneurs drive organic innovation inside large firms.","zh-TW":"內部創業家在大公司內部推動有機創新。"}]', 'business idiom'),
('keep a pulse on', '了解最新動態；密切關注', 'to stay continuously aware of what is happening in a situation', '[{"en":"Leaders should keep a pulse on team morale regularly.","zh-TW":"領導者應該定期了解團隊士氣的最新動態。"},{"en":"Keep a pulse on industry trends to stay ahead.","zh-TW":"密切關注行業趨勢以保持領先。"}]', 'expression'),
('key account management', '重點客戶管理', 'a strategy focused on developing long-term relationships with the most valuable clients', '[{"en":"Key account management requires dedicated relationship managers.","zh-TW":"重點客戶管理需要專職的關係經理。"},{"en":"Our key account management program reduced churn by 30%.","zh-TW":"我們的重點客戶管理計劃將流失率降低了30%。"}]', 'business idiom'),
('key performance indicator', '關鍵績效指標', 'a measurable value that shows how effectively a company is achieving key objectives', '[{"en":"Define clear key performance indicators for each department.","zh-TW":"為每個部門定義清晰的關鍵績效指標。"},{"en":"Tie compensation to key performance indicators.","zh-TW":"將薪酬與關鍵績效指標掛鉤。"}]', 'business idiom'),
('kill it', '表現出色；大殺四方', 'to perform extremely well or achieve great success', '[{"en":"The new sales rep is killing it in the northeast region.","zh-TW":"新銷售代表在東北地區表現出色。"},{"en":"We killed it at the trade show with the new demo.","zh-TW":"我們在貿易展覽上用新演示大殺四方。"}]', 'expression'),
('know your numbers', '了解你的數字；熟悉財務數據', 'to be fully aware of one''s financial metrics and performance data', '[{"en":"Know your numbers before meeting with investors.","zh-TW":"在與投資者見面之前了解你的數字。"},{"en":"Every business leader should know their numbers cold.","zh-TW":"每個商業領導者都應該對財務數據瞭如指掌。"}]', 'expression'),
('knowledge transfer', '知識傳遞；技術交接', 'the process of sharing skills, information, and expertise between people', '[{"en":"Knowledge transfer during handover prevents costly errors.","zh-TW":"交接期間的知識傳遞防止了代價高昂的錯誤。"},{"en":"Invest in knowledge transfer when key employees leave.","zh-TW":"當關鍵員工離職時投資於知識傳遞。"}]', 'business idiom'),
('launch pad', '起點；跳板；發射台', 'a platform or starting point for launching a new initiative', '[{"en":"This partnership serves as a launch pad into Asia.","zh-TW":"這次合作是進入亞洲的跳板。"},{"en":"The pilot program is a launch pad for full deployment.","zh-TW":"試點計劃是全面部署的起點。"}]', 'business idiom'),
('lead magnet', '潛在客戶吸引工具；引流工具', 'a free offer used to attract potential customers and capture their contact information', '[{"en":"The free report acts as a lead magnet for our webinars.","zh-TW":"免費報告作為我們網絡研討會的引流工具。"},{"en":"A strong lead magnet accelerates top-of-funnel growth.","zh-TW":"有力的引流工具加速了漏斗頂端的增長。"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('leave money on the table', '讓錢白白流失；錯失獲利機會', 'to fail to take advantage of all the value available in a deal or situation', '[{"en":"By not upselling we''re leaving money on the table.","zh-TW":"不進行向上銷售，我們讓錢白白流失。"},{"en":"Optimize your pricing to avoid leaving money on the table.","zh-TW":"優化你的定價以避免錯失獲利機會。"}]', 'expression'),
('let the data speak', '讓數據說話；以數據為決策依據', 'to allow evidence and analysis to drive conclusions without bias', '[{"en":"Rather than opinions let the data speak in this review.","zh-TW":"在這次審查中讓數據說話而不是意見。"},{"en":"Let the data speak and you''ll make more confident decisions.","zh-TW":"讓數據說話你會做出更有自信的決策。"}]', 'expression'),
('leverage technology', '善用科技；運用技術優勢', 'to use technological tools to gain efficiency or advantage', '[{"en":"We leverage technology to reduce manual processes.","zh-TW":"我們善用科技來減少手動流程。"},{"en":"Leverage technology to deliver a personalized customer experience.","zh-TW":"運用技術優勢提供個性化的客戶體驗。"}]', 'phrasal verb'),
('lock in prices', '鎖定價格；固定價格', 'to secure a price or rate before it changes', '[{"en":"We locked in prices with our supplier for two years.","zh-TW":"我們與供應商鎖定了兩年的價格。"},{"en":"Lock in prices now before the market rises further.","zh-TW":"趁市場進一步上漲之前鎖定價格。"}]', 'phrasal verb'),
('long-term vision', '長遠願景', 'a clear picture of where an organization aims to be in the distant future', '[{"en":"The CEO shared a long-term vision at the annual meeting.","zh-TW":"執行長在年度會議上分享了長遠願景。"},{"en":"A long-term vision guides daily decision-making.","zh-TW":"長遠願景指導日常決策。"}]', 'business idiom'),
('loss leader', '虧本招徠商品；引流商品', 'a product sold at a loss to attract customers who then buy other profitable items', '[{"en":"The printer was sold as a loss leader to generate ink revenue.","zh-TW":"打印機作為虧本招徠商品銷售以產生墨水收入。"},{"en":"A loss leader strategy works when customer lifetime value is high.","zh-TW":"當客戶終身價值高時虧本招徠策略有效。"}]', 'business idiom'),
('lower the barrier', '降低門檻；減少障礙', 'to make it easier for people to access something or get started', '[{"en":"We lower the barrier to entry with a free trial.","zh-TW":"我們通過免費試用降低了入門門檻。"},{"en":"Lower the barrier for referrals to grow your user base.","zh-TW":"降低推薦門檻以擴大用戶群。"}]', 'expression'),
('make a dent', '取得一定進展；造成明顯影響', 'to make meaningful progress in reducing or solving something large', '[{"en":"This strategy will make a dent in our backlog.","zh-TW":"這個策略將在我們的積壓工作上取得一定進展。"},{"en":"We are starting to make a dent in the market.","zh-TW":"我們開始在市場上造成明顯影響了。"}]', 'expression'),
('make an impact', '產生影響；帶來改變', 'to have a noticeable and significant effect on something', '[{"en":"She made an impact from her very first week.","zh-TW":"她從第一週就產生了影響。"},{"en":"Invest in initiatives that will make an impact at scale.","zh-TW":"投資於能夠帶來大規模影響的計劃。"}]', 'expression'),
('make good on', '兌現；履行（承諾）', 'to fulfill a promise or commitment', '[{"en":"We made good on our promise to cut response times.","zh-TW":"我們兌現了縮短響應時間的承諾。"},{"en":"Make good on your commitments to build stakeholder trust.","zh-TW":"履行你的承諾以建立利益相關者的信任。"}]', 'expression'),
('manage expectations', '管理期望；調整預期', 'to ensure all parties have a realistic understanding of what can be delivered', '[{"en":"Set clear timelines to manage client expectations.","zh-TW":"設定明確的時間表來管理客戶期望。"},{"en":"Managing expectations prevents disappointment and builds trust.","zh-TW":"管理期望防止了失望並建立了信任。"}]', 'expression'),
('market correction', '市場修正；市場調整', 'a temporary decline in asset prices after an excessive rise', '[{"en":"The company prepared for a market correction by building reserves.","zh-TW":"公司通過建立儲備為市場修正做好了準備。"},{"en":"A market correction is healthy for long-term stability.","zh-TW":"市場修正對長期穩定是有益的。"}]', 'business idiom'),
('market dynamics', '市場動態；市場力量', 'the forces and factors that affect supply, demand, and pricing in a market', '[{"en":"Market dynamics shifted rapidly with the new regulations.","zh-TW":"市場動態隨著新規定迅速改變了。"},{"en":"Understanding market dynamics helps you anticipate opportunities.","zh-TW":"了解市場動態幫助你預測機會。"}]', 'business idiom'),
('market penetration', '市場滲透；市場占有', 'the extent to which a product is known and used in a market', '[{"en":"Our goal is to double market penetration within two years.","zh-TW":"我們的目標是在兩年內將市場滲透率翻倍。"},{"en":"Market penetration strategy requires aggressive pricing and promotion.","zh-TW":"市場滲透策略需要積極的定價和促銷。"}]', 'business idiom'),
('market saturation', '市場飽和', 'the point at which most potential customers in a market already use a product', '[{"en":"Market saturation forced the brand to innovate.","zh-TW":"市場飽和迫使品牌進行創新。"},{"en":"Diversify when facing market saturation in your core segment.","zh-TW":"面對核心細分市場的飽和時進行多元化。"}]', 'business idiom'),
('market share grab', '搶奪市場份額；爭取市場份額', 'an aggressive strategy to rapidly capture a larger portion of the market', '[{"en":"The pricing campaign was a market share grab.","zh-TW":"定價活動是一次搶奪市場份額的行動。"},{"en":"A market share grab requires significant upfront investment.","zh-TW":"爭取市場份額需要大量前期投資。"}]', 'expression'),
('meaningful metrics', '有意義的指標；重要的衡量標準', 'measurements that provide genuine insight into performance', '[{"en":"Focus on meaningful metrics not just vanity numbers.","zh-TW":"專注於有意義的指標而不只是虛榮數字。"},{"en":"Meaningful metrics guide strategic decisions effectively.","zh-TW":"有意義的指標有效地指導策略決策。"}]', 'expression'),
('milestone-based payment', '里程碑付款；分階段付款', 'a payment structure tied to the completion of specific project milestones', '[{"en":"We use a milestone-based payment structure for long projects.","zh-TW":"對長期專案我們使用里程碑付款結構。"},{"en":"Milestone-based payment reduces financial risk for both parties.","zh-TW":"里程碑付款降低了雙方的財務風險。"}]', 'business idiom'),
('minimize friction', '減少摩擦；降低阻力', 'to remove obstacles or inefficiencies from a process or interaction', '[{"en":"Minimize friction in the checkout process to increase conversions.","zh-TW":"減少結帳流程中的摩擦以增加轉換率。"},{"en":"Minimize friction between teams through clear communication norms.","zh-TW":"通過清晰的溝通規範降低團隊間的阻力。"}]', 'phrasal verb'),
('mission-critical', '任務關鍵性的；至關重要的', 'essential for the success of an operation or organization', '[{"en":"Prioritize mission-critical systems in the upgrade plan.","zh-TW":"在升級計劃中優先考慮至關重要的系統。"},{"en":"Mission-critical tasks should never be deprioritized.","zh-TW":"任務關鍵性的工作永遠不應該降低優先級。"}]', 'business idiom'),
('mobilize resources', '動員資源；調配資源', 'to organize and prepare resources for action', '[{"en":"We mobilized resources across four countries for the launch.","zh-TW":"我們動員了四個國家的資源進行發布。"},{"en":"Mobilize resources quickly when a strategic opportunity arises.","zh-TW":"當戰略機會出現時迅速調配資源。"}]', 'phrasal verb'),
('model behavior', '樹立榜樣；以身作則', 'to demonstrate the behaviors you want others to follow', '[{"en":"Leaders must model behavior that reflects company values.","zh-TW":"領導者必須樹立反映公司價值觀的榜樣。"},{"en":"Model behavior around accountability and transparency.","zh-TW":"在問責制和透明度方面以身作則。"}]', 'expression'),
('multistakeholder approach', '多方利益相關者方法', 'a strategy that involves and balances the interests of multiple parties', '[{"en":"A multistakeholder approach ensures all voices are heard.","zh-TW":"多方利益相關者方法確保所有聲音都被聽到。"},{"en":"ESG initiatives require a multistakeholder approach.","zh-TW":"ESG倡議需要多方利益相關者方法。"}]', 'business idiom'),
('mutual benefit', '互惠互利；共同受益', 'an arrangement that advantages all parties involved', '[{"en":"The partnership was designed for mutual benefit.","zh-TW":"這次合作是為了互惠互利而設計的。"},{"en":"Mutual benefit is the foundation of lasting business relationships.","zh-TW":"互惠互利是持久商業關係的基礎。"}]', 'expression'),
('navigate ambiguity', '應對模糊性；在不確定中前行', 'to make effective decisions when the situation is unclear or uncertain', '[{"en":"Strong leaders navigate ambiguity without losing confidence.","zh-TW":"強大的領導者在不確定中前行而不失去信心。"},{"en":"The ability to navigate ambiguity is crucial in fast-moving markets.","zh-TW":"應對模糊性的能力在快速變化的市場中至關重要。"}]', 'phrasal verb'),
('net promoter score', '淨推薦值', 'a metric measuring customer loyalty by how likely they are to recommend a company', '[{"en":"Our net promoter score increased 15 points after the redesign.","zh-TW":"重新設計後我們的淨推薦值增加了15分。"},{"en":"Net promoter score is a leading indicator of customer retention.","zh-TW":"淨推薦值是客戶留存率的領先指標。"}]', 'business idiom'),
('new normal', '新常態', 'a previously uncommon situation that has become standard practice', '[{"en":"Remote work has become the new normal for many industries.","zh-TW":"遠端工作已成為許多行業的新常態。"},{"en":"Adapt your strategy to thrive in the new normal.","zh-TW":"調整你的策略在新常態中蓬勃發展。"}]', 'business idiom'),
('not cut out for', '不適合；沒有能力做', 'to not have the right abilities or temperament for something', '[{"en":"He realized he was not cut out for sales and moved to operations.","zh-TW":"他意識到自己不適合銷售，轉去了運營部門。"},{"en":"Not everyone is cut out for the pressure of leadership.","zh-TW":"不是每個人都有能力承受領導層的壓力。"}]', 'expression'),
('object strenuously', '強烈反對；力排眾議', 'to oppose something strongly and with urgency', '[{"en":"Several directors objected strenuously to the cost reduction plan.","zh-TW":"幾位董事強烈反對成本削減計劃。"},{"en":"Object strenuously when a decision will harm the team.","zh-TW":"當一個決定會傷害團隊時強烈反對。"}]', 'phrasal verb'),
('on a roll', '連續成功；勢頭強勁', 'experiencing a series of successes or positive momentum', '[{"en":"The team is on a roll after three consecutive record quarters.","zh-TW":"在連續三個破紀錄的季度後團隊勢頭強勁。"},{"en":"We''re on a roll — keep up the momentum.","zh-TW":"我們連續成功——保持這個勢頭。"}]', 'expression'),
('on board with', '同意；支持；加入', 'in agreement with and supporting a plan or decision', '[{"en":"We need all managers on board with the new policy.","zh-TW":"我們需要所有經理同意這個新政策。"},{"en":"Once leadership is on board with the vision execution accelerates.","zh-TW":"一旦領導層支持這個願景，執行就會加速。"}]', 'expression'),
('on your radar', '在你的關注範圍內；被你注意到', 'something you are aware of and monitoring', '[{"en":"Keep emerging technologies on your radar.","zh-TW":"把新興技術保持在你的關注範圍內。"},{"en":"Is the regulatory change on your radar for planning?","zh-TW":"監管變化是否在你的規劃關注範圍內？"}]', 'expression'),
('operational excellence', '卓越運營；業務卓越', 'a commitment to improving processes and performance continuously', '[{"en":"Operational excellence differentiates us from competitors.","zh-TW":"卓越運營使我們與競爭對手有所區別。"},{"en":"We invest in operational excellence through training and systems.","zh-TW":"我們通過培訓和系統投資於業務卓越。"}]', 'business idiom'),
('opportunity cost', '機會成本', 'the value of the best alternative forgone when making a decision', '[{"en":"The opportunity cost of delaying the launch is significant.","zh-TW":"延遲發布的機會成本是顯著的。"},{"en":"Consider the opportunity cost before saying no to a project.","zh-TW":"在拒絕一個專案之前考慮機會成本。"}]', 'business idiom'),
('organic traffic', '有機流量；自然流量', 'visitors who arrive at a website through unpaid search results', '[{"en":"SEO investment doubled our organic traffic.","zh-TW":"SEO投資使我們的有機流量翻倍了。"},{"en":"Organic traffic reduces long-term customer acquisition cost.","zh-TW":"自然流量降低了長期客戶獲取成本。"}]', 'business idiom'),
('out of commission', '停用中；停止運作', 'not working or not available for use', '[{"en":"The server was out of commission for three hours.","zh-TW":"伺服器停止運作了三小時。"},{"en":"Three team members are out of commission due to illness.","zh-TW":"三位團隊成員因病停工中。"}]', 'prepositional phrase'),
('overdeliver on', '超越承諾；超出預期交付', 'to provide more than what was promised or expected', '[{"en":"We aim to overdeliver on every client commitment.","zh-TW":"我們致力於在每個客戶承諾上超越預期交付。"},{"en":"Overdelivering on quality builds long-term loyalty.","zh-TW":"在品質上超出預期建立了長期忠誠度。"}]', 'phrasal verb'),
('pace of change', '變革的步調；變化速度', 'the speed at which change is happening in an industry or organization', '[{"en":"The pace of change in technology is unprecedented.","zh-TW":"技術變革的步調是前所未有的。"},{"en":"Companies that match the pace of change thrive.","zh-TW":"能夠跟上變化速度的公司才能蓬勃發展。"}]', 'expression'),
('participate in', '參與；參加', 'to take part in an activity, discussion, or process', '[{"en":"All team leaders must participate in the strategy workshop.","zh-TW":"所有團隊領導者必須參加策略研討會。"},{"en":"We participate in industry forums to stay connected.","zh-TW":"我們參加行業論壇以保持聯繫。"}]', 'phrasal verb'),
('path of least resistance', '阻力最小的路；容易做的選擇', 'the easiest course of action, often at the expense of long-term results', '[{"en":"Don''t take the path of least resistance in strategy.","zh-TW":"在策略上不要選擇阻力最小的路。"},{"en":"The team took the path of least resistance and chose familiar tools.","zh-TW":"團隊選擇了容易做的選擇，使用了熟悉的工具。"}]', 'expression'),
('performance gap', '績效差距', 'the difference between current performance and desired performance', '[{"en":"We identified a performance gap in the sales team.","zh-TW":"我們識別了銷售團隊的績效差距。"},{"en":"Close the performance gap through targeted coaching.","zh-TW":"通過針對性的輔導縮小績效差距。"}]', 'business idiom'),
('performance review', '績效評估；績效考核', 'a formal evaluation of an employee''s work and achievements', '[{"en":"Annual performance reviews help identify development needs.","zh-TW":"年度績效評估有助於識別發展需求。"},{"en":"Tie promotions to objective performance review criteria.","zh-TW":"將晉升與客觀的績效考核標準掛鉤。"}]', 'business idiom'),
('pilot program', '試點計劃；試行方案', 'a small-scale test or trial run of a larger program', '[{"en":"We ran a pilot program in three cities before the national launch.","zh-TW":"全國推出前我們在三個城市進行了試點計劃。"},{"en":"A pilot program reduces risk of large-scale failure.","zh-TW":"試點計劃降低了大規模失敗的風險。"}]', 'business idiom'),
('play the long game', '下長遠棋；著眼長期', 'to focus on long-term outcomes rather than short-term gains', '[{"en":"We play the long game by investing in customer relationships.","zh-TW":"我們通過投資客戶關係下長遠棋。"},{"en":"Playing the long game builds sustainable competitive advantage.","zh-TW":"著眼長期建立了可持續的競爭優勢。"}]', 'expression'),
('point of no return', '回不了頭的那一步；不歸點', 'the stage at which a decision or action can no longer be reversed', '[{"en":"Signing the contract is the point of no return.","zh-TW":"簽署合約是回不了頭的那一步。"},{"en":"We assessed risks before reaching the point of no return.","zh-TW":"我們在到達不歸點之前評估了風險。"}]', 'expression'),
('post-mortem analysis', '事後分析；項目覆盤', 'a review conducted after a project to assess what worked and what didn''t', '[{"en":"The post-mortem analysis revealed key lessons from the launch.","zh-TW":"事後分析揭示了發布的關鍵教訓。"},{"en":"Schedule a post-mortem within two weeks of project completion.","zh-TW":"在專案完成後兩週內安排項目覆盤。"}]', 'business idiom'),
('product-market fit', '產品市場契合度', 'the degree to which a product satisfies strong market demand', '[{"en":"The startup struggled to find product-market fit.","zh-TW":"新創公司努力尋求產品市場契合度。"},{"en":"Once you have product-market fit scale aggressively.","zh-TW":"一旦你達到產品市場契合度就積極擴大規模。"}]', 'business idiom'),
('profit center', '利潤中心', 'a department or unit that generates its own revenue and profits', '[{"en":"We transformed the consulting arm into a profit center.","zh-TW":"我們將諮詢部門轉變為利潤中心。"},{"en":"Each region operates as an independent profit center.","zh-TW":"每個地區作為獨立的利潤中心運作。"}]', 'business idiom'),
('proactively address', '主動解決；積極應對', 'to deal with something before it becomes a larger problem', '[{"en":"Proactively address compliance risks before the audit.","zh-TW":"在審計之前主動解決合規風險。"},{"en":"She proactively addressed the team''s concerns in a meeting.","zh-TW":"她在會議中積極應對了團隊的擔憂。"}]', 'phrasal verb'),
('pull levers', '採取措施；使用可用手段', 'to use available tools or mechanisms to achieve a desired result', '[{"en":"We pulled multiple levers to boost Q4 revenue.","zh-TW":"我們採取了多項措施來提升第四季收入。"},{"en":"Identify which levers to pull for the fastest impact.","zh-TW":"識別哪些手段能產生最快的影響。"}]', 'expression');